# ast_nodes.py
from dataclasses import dataclass, field
from typing import Optional, List

@dataclass
class Num:
    value: int
    line:  int = 0

@dataclass
class Bool:
    value: bool
    line:  int = 0

@dataclass
class Var:
    name: str
    line: int = 0

@dataclass
class BinOp:
    op:    str
    left:  object
    right: object
    line:  int = 0

@dataclass
class IfExpr:
    cond:  object
    then_: object
    else_: object
    line:  int = 0

@dataclass
class Let:
    name:  str
    value: object
    body:  object
    line:  int = 0

@dataclass
class LetRec:
    name:  str
    value: object
    body:  object
    line:  int = 0

@dataclass
class Fun:
    param: str
    body:  object
    line:  int = 0

@dataclass
class App:
    func: object
    arg:  object
    line: int = 0

print("AST node classes defined.")
